const crypto = require('crypto');
const inputItem = $input.first()?.json || {};
const headers = inputItem.headers || {};
const query = inputItem.query || {};
const body = inputItem.body || {};

// 1. Meta Webhook GET Challenge Verification
if (query['hub.mode'] === 'subscribe' && query['hub.challenge']) {
  const configuredVerifyToken = $env.META_VERIFY_TOKEN;
  const providedToken = query['hub.verify_token'] || '';

  // FAIL-CLOSED: missing env var = reject
  if (!configuredVerifyToken) {
    return [{
      json: {
        is_verification: true,
        verification_passed: false,
        error: 'Server configuration error: META_VERIFY_TOKEN is not set'
      }
    }];
  }

  let isVerifyValid = false;
  if (providedToken) {
    try {
      const bufA = Buffer.from(configuredVerifyToken, 'utf8');
      const bufB = Buffer.from(providedToken, 'utf8');
      if (bufA.length === bufB.length && crypto.timingSafeEqual(bufA, bufB)) {
        isVerifyValid = true;
      }
    } catch (e) {
      isVerifyValid = false;
    }
  }

  if (isVerifyValid) {
    return [{
      json: {
        is_verification: true,
        verification_passed: true,
        challenge: query['hub.challenge']
      }
    }];
  } else {
    return [{
      json: {
        is_verification: true,
        verification_passed: false,
        error: 'Invalid verification token'
      }
    }];
  }
}

// 2. Meta Webhook HMAC-SHA256 Signature Verification (FAIL-CLOSED)
const appSecret = $env.META_APP_SECRET;
const signatureHeader = headers['x-hub-signature-256'] || headers['X-Hub-Signature-256'] || '';

// Missing app secret = reject immediately
if (!appSecret) {
  return [{
    json: {
      is_signature_invalid: true,
      error: 'Server configuration error: META_APP_SECRET is not set'
    }
  }];
}

// Missing signature header = reject immediately
if (!signatureHeader) {
  return [{
    json: {
      is_signature_invalid: true,
      error: 'Missing X-Hub-Signature-256 header'
    }
  }];
}

let isSignatureValid = false;
try {
  const rawPayload = inputItem.rawBody || (typeof body === 'string' ? body : JSON.stringify(body));
  const expectedSig = 'sha256=' + crypto.createHmac('sha256', appSecret).update(rawPayload).digest('hex');
  const sigBuffer = Buffer.from(signatureHeader, 'utf8');
  const expectedBuffer = Buffer.from(expectedSig, 'utf8');
  if (sigBuffer.length === expectedBuffer.length && crypto.timingSafeEqual(sigBuffer, expectedBuffer)) {
    isSignatureValid = true;
  }
} catch (e) {
  isSignatureValid = false;
}

if (!isSignatureValid) {
  return [{
    json: {
      is_signature_invalid: true,
      error: 'Invalid HMAC-SHA256 signature'
    }
  }];
}

// 3. Inbound Payload Normalization & Status Event Filtering
let entry = (body.entry && body.entry[0]) || {};
let change = (entry.changes && entry.changes[0]) || {};
let val = change.value || {};

if (val.statuses && Array.isArray(val.statuses) && val.statuses.length > 0) {
  return [{
    json: {
      is_status_callback: true,
      status_detail: val.statuses[0]?.status,
      message_id: val.statuses[0]?.id
    }
  }];
}

const rawMessages = (val.messages && Array.isArray(val.messages)) ? val.messages : [];
if (rawMessages.length === 0 && !body.From && !body.phone && !body.message) {
  return [{
    json: {
      is_status_callback: true,
      reason: 'No message content in webhook payload'
    }
  }];
}

const results = [];
const contact = (val.contacts && val.contacts[0]) || {};
const defaultCustomerName = contact.profile?.name || body.ProfileName || body.name || body.customer_name || 'Valued Patient';
const messagesToProcess = rawMessages.length > 0 ? rawMessages : [body];

for (const msgObj of messagesToProcess) {
  let rawPhone = '';
  let customerName = defaultCustomerName;
  let message = '';
  let channel = 'whatsapp_cloud';

  if (msgObj.from) {
    rawPhone = msgObj.from;
    message = msgObj.text?.body || msgObj.button?.text || msgObj.interactive?.button_reply?.title || msgObj.interactive?.list_reply?.title || '';
  } else if (body.From) {
    rawPhone = (body.From || '').replace('whatsapp:', '').trim();
    message = body.Body || '';
    channel = 'twilio';
  } else {
    rawPhone = String(body.phone || body.from || body.sender || '').trim();
    message = body.message || body.text || body.body || '';
  }

  // Canonical phone normalization: digits only, 10-digit -> prepend 91
  let cleanPhone = String(rawPhone || '').replace(/[^0-9]/g, '');
  if (cleanPhone.length === 10) {
    cleanPhone = '91' + cleanPhone;
  }

  // Deterministic message ID: use platform ID if present, else SHA-256 of phone+message+timestamp
  let messageId = msgObj.id || body.MessageSid || body.message_id;
  if (!messageId) {
    const payloadHash = crypto.createHash('sha256')
      .update(cleanPhone + ':' + message.trim() + ':' + (msgObj.timestamp || body.timestamp || ''))
      .digest('hex');
    messageId = 'det_msg_' + payloadHash;
  }

  const correlationId = 'corr_' + crypto.createHash('sha256').update(messageId).digest('hex').substring(0, 16);

  results.push({
    json: {
      is_verification: false,
      is_status_callback: false,
      is_signature_invalid: false,
      message_id: messageId,
      correlation_id: correlationId,
      phone: cleanPhone,
      customer_name: customerName,
      message: (message || '').trim(),
      channel: channel,
      received_at: new Date().toISOString()
    }
  });
}

return results;

const inbound = $('Parse_WhatsApp_Inbound').first().json;
const dbRes = $input.first()?.json || {};

// Explicit DB failure check
const isDbError = Boolean(dbRes.error) || !Array.isArray(dbRes.active_doctors);
if (isDbError) {
  return [{
    json: {
      correlation_id: inbound.correlation_id,
      phone: inbound.phone,
      customer_name: inbound.customer_name,
      message: inbound.message,
      channel: inbound.channel,
      db_error: true,
      error_msg: "Database service is temporarily unavailable."
    }
  }];
}

// Pre-LLM Rate Limiting
if (Number(dbRes.recent_msg_count || 0) > 15) {
  return [{
    json: {
      correlation_id: inbound.correlation_id,
      phone: inbound.phone,
      customer_name: inbound.customer_name,
      message: inbound.message,
      channel: inbound.channel,
      is_rate_limited: true,
      error_msg: "You are sending messages too quickly. Please wait a minute before sending another request."
    }
  }];
}

const doctors = dbRes.active_doctors;
const appts = Array.isArray(dbRes.recent_appointments) ? dbRes.recent_appointments : [];
const unavailability = Array.isArray(dbRes.active_unavailability) ? dbRes.active_unavailability : [];

// Check for active PENDING (that is NOT expired)
const now = new Date();
const activePending = appts.find(a => a.status === 'PENDING' && (!a.expires_at || new Date(a.expires_at) > now));
const activeConfirmed = appts.find(a => (a.status === 'CONFIRMED' || a.status === 'RESCHEDULED') && new Date(a.end_time) > now);

const clinicName = $env.CLINIC_NAME || 'Apex Healthcare Clinic';
const clinicTimezone = doctors[0]?.timezone || $env.CLINIC_TIMEZONE || 'Asia/Kolkata';
const todayLocalStr = new Intl.DateTimeFormat('en-CA', { timeZone: clinicTimezone }).format(now);
const todayWeekday = new Intl.DateTimeFormat('en-US', { timeZone: clinicTimezone, weekday: 'long' }).format(now);

const docListDesc = doctors.length > 0
  ? doctors.map(d => `- ID: "${d.doctor_id}", Name: "${d.doctor_name}", Specialty: "${d.specialty}", Working Hours: ${d.working_hours.start}-${d.working_hours.end}`).join('\n')
  : 'No doctors are currently available at the clinic.';

const prompt = `You are an intelligent clinic receptionist AI for ${clinicName}.
Today's local date is ${todayLocalStr} (${todayWeekday}) in ${clinicTimezone} timezone.

Doctors available at clinic:
${docListDesc}

Customer Info:
- Name: "${inbound.customer_name || 'Customer'}"
- Phone: "${inbound.phone}"
- Latest Message: "${inbound.message}"

Active Holds/Bookings:
- Pending Hold: ${activePending ? JSON.stringify(activePending) : 'None'}
- Confirmed Booking: ${activeConfirmed ? JSON.stringify(activeConfirmed) : 'None'}

Tasks:
Analyze the message and extract Intent and Entities.
Intents: "BOOK", "CHECK_AVAILABILITY", "CONFIRM", "RESCHEDULE", "CANCEL", "GENERAL_QUESTIONS", "UNKNOWN"
Rules:
- If customer says "YES", "CONFIRM", "OK", "Sure", "book it" and there is a Pending Hold -> Intent MUST be "CONFIRM".
- DO NOT invent calendar availability.
- If no doctors are available, inform the patient politely.
- Extract requested_date (YYYY-MM-DD), requested_time (HH:MM in 24h), doctor_id (must match one of [${doctors.map(d => d.doctor_id).join(', ')}]), service.

Output MUST be a single raw JSON object:
{
  "intent": "BOOK" | "CHECK_AVAILABILITY" | "CONFIRM" | "RESCHEDULE" | "CANCEL" | "GENERAL_QUESTIONS" | "UNKNOWN",
  "doctor_id": string | null,
  "service": string | null,
  "requested_date": "YYYY-MM-DD" | null,
  "requested_time": "HH:MM" | null,
  "general_answer": string | null
}`;

return [{
  json: {
    correlation_id: inbound.correlation_id,
    phone: inbound.phone,
    customer_name: inbound.customer_name,
    message: inbound.message,
    channel: inbound.channel,
    db_error: false,
    is_rate_limited: false,
    active_doctors: doctors,
    active_pending: activePending || null,
    active_confirmed: activeConfirmed || null,
    active_unavailability: unavailability,
    today_local: todayLocalStr,
    clinic_name: clinicName,
    clinic_timezone: clinicTimezone,
    gemini_model: $env.GEMINI_MODEL || "gemini-2.0-flash",
    gemini_prompt: prompt
  }
}];

const prev = $('Merge_Context_For_AI').first().json;
const response = $input.item.json;
const doctors = prev.active_doctors || [];

let isError = false;
let errorMessage = '';

let aiResult = {
  intent: 'GENERAL_QUESTIONS',
  doctor_id: null,
  service: 'General Consultation',
  requested_date: null,
  requested_time: null,
  general_answer: null
};

const cleanMsg = (prev.message || '').trim().toLowerCase();
const isDirectConfirm = ['yes', 'confirm', 'y', 'sure', 'ok', 'okay', 'proceed', 'book it', 'yes please', 'confirm please'].includes(cleanMsg);

if (prev.active_pending && isDirectConfirm) {
  aiResult.intent = 'CONFIRM';
  aiResult.doctor_id = prev.active_pending.doctor_id;
  aiResult.service = prev.active_pending.service;
} else if (response && response.candidates && response.candidates[0]?.content?.parts?.[0]?.text) {
  try {
    let rawText = response.candidates[0].content.parts[0].text.trim();
    if (rawText.startsWith('```json')) {
      rawText = rawText.replace(/^```json\n?/, '').replace(/\n?```$/, '');
    } else if (rawText.startsWith('```')) {
      rawText = rawText.replace(/^```\n?/, '').replace(/\n?```$/, '');
    }
    const parsed = JSON.parse(rawText);
    aiResult = { ...aiResult, ...parsed };
  } catch (e) {
    isError = true;
    errorMessage = 'Failed to parse AI intent response.';
  }
} else {
  isError = true;
  errorMessage = 'AI service temporarily unavailable.';
}

// Strict deterministic doctor validation (Bug #3)
let matchedDoctor = null;
if (aiResult.doctor_id) {
  const reqDoc = String(aiResult.doctor_id).trim().toLowerCase();
  matchedDoctor = doctors.find(d => 
    d.doctor_id.toLowerCase() === reqDoc || 
    d.doctor_name.toLowerCase().includes(reqDoc) ||
    d.specialty.toLowerCase().includes(reqDoc)
  ) || null;
}

// If no doctor was explicitly requested:
if (!matchedDoctor && !aiResult.doctor_id) {
  if (doctors.length === 1) {
    matchedDoctor = doctors[0];
  } else if (prev.active_pending && (aiResult.intent === 'CONFIRM' || aiResult.intent === 'CANCEL')) {
    matchedDoctor = doctors.find(d => d.doctor_id === prev.active_pending.doctor_id) || null;
  } else if (prev.active_confirmed && (aiResult.intent === 'RESCHEDULE' || aiResult.intent === 'CANCEL')) {
    matchedDoctor = doctors.find(d => d.doctor_id === prev.active_confirmed.doctor_id) || null;
  }
}

// Strict Date validation (YYYY-MM-DD)
function isValidDate(dateStr) {
  if (!dateStr || typeof dateStr !== 'string') return false;
  const match = dateStr.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!match) return false;
  const [_, yStr, mStr, dStr] = match;
  const y = Number(yStr), m = Number(mStr), d = Number(dStr);
  if (m < 1 || m > 12 || d < 1 || d > 31) return false;
  const testDate = new Date(Date.UTC(y, m - 1, d));
  return testDate.getUTCFullYear() === y && testDate.getUTCMonth() === (m - 1) && testDate.getUTCDate() === d;
}

// Strict Time validation (HH:MM 00:00 - 23:59)
function isValidTime(timeStr) {
  if (!timeStr || typeof timeStr !== 'string') return false;
  return /^([01]\d|2[0-3]):([0-5]\d)$/.test(timeStr);
}

if (!isValidDate(aiResult.requested_date)) {
  aiResult.requested_date = null;
}
if (!isValidTime(aiResult.requested_time)) {
  aiResult.requested_time = null;
}

return [{
  json: {
    correlation_id: prev.correlation_id,
    phone: prev.phone,
    customer_name: prev.customer_name,
    message: prev.message,
    channel: prev.channel,
    is_ai_error: isError,
    ai_error_message: errorMessage,
    intent: isError ? 'AI_ERROR' : (aiResult.intent || 'GENERAL_QUESTIONS').toUpperCase(),
    doctor: matchedDoctor,
    requested_doctor_raw: aiResult.doctor_id || null,
    service: aiResult.service || 'General Consultation',
    requested_date: aiResult.requested_date,
    requested_time: aiResult.requested_time,
    general_answer: aiResult.general_answer,
    active_pending: prev.active_pending,
    active_confirmed: prev.active_confirmed,
    active_unavailability: prev.active_unavailability,
    active_doctors: prev.active_doctors
  }
}];

function getUtcFromLocal(dateStr, timeStr, timeZone) {
  const [yyyy, mm, dd] = dateStr.split('-').map(Number);
  const [hh, min] = timeStr.split(':').map(Number);
  const testUtc = new Date(Date.UTC(yyyy, mm - 1, dd, hh, min, 0));

  const dtf = new Intl.DateTimeFormat('en-US', {
    timeZone,
    year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', second: '2-digit',
    hour12: false
  });

  const parts = dtf.formatToParts(testUtc);
